function client(initial, live, token) {
  const $=id=>document.getElementById(id);
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const name=t=>(t?.title||'名称待核实')+'（'+(t?.id||'?')+'）';
  const labels=Object.assign(Object.create(null),{ready:'可领取',in_progress:'进行中',awaiting_integration:'待集成',pending:'等待依赖',blocked:'受阻',needs_arch_review:'需裁决',failed:'失败',done:'已完成',unknown:'未映射'});
  const kinds=Object.assign(Object.create(null),{development:'开发',verification:'阶段验证',acceptance:'业务验收',unclassified:'未分类'});
  let state=initial, prefs={view:'board',query:'',owner:'',status:'',theme:'system',collapsed:['done']}, selected=null, returnTask=null, tab='requirements', lastFocus=null, selectedWt='', generation=0;
  try{Object.assign(prefs,JSON.parse(localStorage.getItem('task-preview:'+state.key)||'{}'));}catch{}
  prefs.collapsed=(prefs.collapsed||[]).filter(status=>status!=='done');
  if(prefs.view==='roadmap')prefs.view='graph';
  if(prefs.theme==='system')prefs.theme=matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light';
  document.querySelector('.brand')?.remove();
  $('source')?.remove();
  document.querySelector('.footer-note')?.remove();
  document.querySelector('.sidebar-footer').innerHTML='<button class="theme-toggle" id="theme-toggle" type="button"></button>';
  let graphZoom=1, graphOpen=new Set(), graphShowOtherRoots=false, graphFocus='TASK-001';
  const save=()=>{try{localStorage.setItem('task-preview:'+state.key,JSON.stringify(prefs));}catch{}};
  const task=id=>state.tasks.find(t=>t.id===id);
  const status=t=>labels[t.status]||'未映射：'+t.status;
  const stamp=d=>d&&!isNaN(Date.parse(d))?new Date(d).toLocaleString():d||'未知';
  const blocked=t=>t.dependencies.filter(d=>task(d)?.status!=='done');
  const badge=t=>'<span class="badge '+(Object.hasOwn(labels,t.status)?t.status:'unknown')+'">'+esc(status(t))+'</span>';
  const button=(t,cls='task')=>'<button class="'+cls+'" data-task="'+esc(t.id)+'">'+esc(name(t))+'</button>';
  const commitTone=c=>/^(fix|hotfix)(\(|:)/i.test(c.subject)?'commit-fix':/^(feat|integrate)(\(|:)/i.test(c.subject)?'commit-feature':/^(test|verify)(\(|:)/i.test(c.subject)?'commit-test':/^(docs|tasks)(\(|:)/i.test(c.subject)?'commit-record':'commit-neutral';
  const valueList=v=>Array.isArray(v)?v:(v==null||v===''?[]:[v]);
  const readable=v=>typeof v==='string'?v:JSON.stringify(v);
  function scopeView(scope){
    const definitions=[['in','本卡负责','scope-in'],['out','不包含','scope-out']];
    const known=new Set(definitions.map(x=>x[0]));
    const cards=definitions.map(([key,label,tone])=>valueList(scope?.[key]).length?'<section class="scope-card '+tone+'"><h4>'+label+'</h4><ul>'+valueList(scope[key]).map(x=>'<li>'+esc(readable(x))+'</li>').join('')+'</ul></section>':'').join('');
    const extra=Object.entries(scope||{}).filter(([key])=>!known.has(key)).map(([key,value])=>'<section class="scope-card"><h4>'+esc(key)+'</h4><ul>'+valueList(value).map(x=>'<li>'+esc(readable(x))+'</li>').join('')+'</ul></section>').join('');
    return cards+extra||'<p class="empty-state">未记录任务范围</p>';
  }
  const acceptanceText=a=>typeof a==='string'?a:a.expect||a.run||a.check||a.summary||readable(a);
  const inline=s=>esc(s)
    .replace(/`([^`]+)`/g,'<code>$1</code>')
    .replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>')
    .replace(/\*([^*]+)\*/g,'<em>$1</em>')
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,label,url)=>{
      const decoded=url.replaceAll('&amp;','&');
      return /^(https?:\/\/|#|\.?\.?\/)/.test(decoded)?'<a href="'+esc(decoded)+'" target="_blank" rel="noreferrer">'+label+'</a>':label;
    });
  function markdown(source){
    const lines=String(source||'').replace(/\r\n?/g,'\n').split('\n'),out=[];let code=false,codeLines=[],listType='';
    const closeList=()=>{if(listType){out.push('</'+listType+'>');listType='';}};
    for(let i=0;i<lines.length;i++){
      const line=lines[i];
      if(/^```/.test(line)){closeList();if(code){out.push('<pre><code>'+esc(codeLines.join('\n'))+'</code></pre>');code=false;codeLines=[];}else code=true;continue;}
      if(code){codeLines.push(line);continue;}
      if(/^\s*\|?.+\|.+\|?\s*$/.test(line)&&i+1<lines.length&&/^\s*\|?\s*:?-+/.test(lines[i+1])){
        closeList();const rows=[line];let cursor=i+2;while(cursor<lines.length&&/^\s*\|?.+\|.+\|?\s*$/.test(lines[cursor]))rows.push(lines[cursor++]);i=cursor-1;
        const cells=r=>r.trim().replace(/^\||\|$/g,'').split('|').map(x=>x.trim());
        out.push('<div class="md-table"><table><thead><tr>'+cells(rows[0]).map(c=>'<th>'+inline(c)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(1).map(r=>'<tr>'+cells(r).map(c=>'<td>'+inline(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>');continue;
      }
      const heading=line.match(/^(#{1,6})\s+(.+)$/);if(heading){closeList();out.push('<h'+heading[1].length+'>'+inline(heading[2])+'</h'+heading[1].length+'>');continue;}
      const item=line.match(/^\s*([-*+] |\d+\. )(.+)$/);if(item){const wanted=/\d/.test(item[1])?'ol':'ul';if(listType!==wanted){closeList();out.push('<'+wanted+'>');listType=wanted;}out.push('<li>'+inline(item[2])+'</li>');continue;}
      closeList();
      if(!line.trim()){continue;}
      if(/^\s*>\s?/.test(line)){out.push('<blockquote>'+inline(line.replace(/^\s*>\s?/,''))+'</blockquote>');continue;}
      if(/^\s*(-{3,}|\*{3,})\s*$/.test(line)){out.push('<hr>');continue;}
      out.push('<p>'+inline(line)+'</p>');
    }
    closeList();if(code)out.push('<pre><code>'+esc(codeLines.join('\n'))+'</code></pre>');return out.join('');
  }
  function filtered(){return state.tasks.filter(t=>!prefs.query||(name(t)+' '+t.owner).toLowerCase().includes(prefs.query.toLowerCase()));}
  function bindTasks(el){el.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>open(b.dataset.task));}
  function render(){
    document.documentElement.dataset.theme=prefs.theme;
    $('project').textContent='项目进度预览（'+state.project+'）';
    $('header-search').hidden=prefs.view==='architecture';
    $('query').value=prefs.query;
    $('theme-toggle').innerHTML=prefs.theme==='light'?'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M4.9 4.9l1.4 1.4M17.7 17.7l1.4 1.4M2 12h2M20 12h2M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 15.2A8.5 8.5 0 018.8 4a8.5 8.5 0 1011.2 11.2z"/></svg>';
    $('theme-toggle').setAttribute('aria-label',prefs.theme==='dark'?'切换到浅色主题':'切换到深色主题');
    $('theme-toggle').title=prefs.theme==='dark'?'切换到浅色主题':'切换到深色主题';
    document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===prefs.view)));
    const scrolls=[...$('content').querySelectorAll('[data-scroll]')].map(e=>[e.dataset.scroll,e.scrollTop,e.scrollLeft]);
    const x=$('content').scrollLeft,y=$('content').scrollTop;
    const rows=filtered();
    if(prefs.view==='overview') overview(rows);
    else if(prefs.view==='graph') graph(rows);
    else if(prefs.view==='architecture') architecture();
    else board(rows);
    bindTasks($('content'));
    for(const [id,top,left] of scrolls){const e=[...$('content').querySelectorAll('[data-scroll]')].find(e=>e.dataset.scroll===id);if(e){e.scrollTop=top;e.scrollLeft=left;}}
    $('content').scrollLeft=x;$('content').scrollTop=y;
  }
  function overview(rows){
    const done=rows.filter(t=>t.status==='done').length;
    const percent=rows.length?Math.round(done/rows.length*100):0;
    const active=rows.filter(t=>t.status==='in_progress');
    const completed=rows.filter(t=>t.status==='done').sort((a,b)=>(Date.parse(b.completedAt)||0)-(Date.parse(a.completedAt)||0)).slice(0,20);
    const recent=(state.recent?.commits||[]).slice(0,10);
    const taskRows=items=>items.map(t=>'<div class="overview-task">'+button(t)+'<small>'+esc(t.owner||'未分配')+(t.completedAt?' · '+esc(stamp(t.completedAt)):'')+'</small></div>').join('');
    $('content').innerHTML='<div class="overview"><div class="overview-column"><section><h2>交付概览</h2><div class="delivery-totals"><strong class="number">'+done+' <small>/ '+rows.length+'</small></strong><span>总提交数：<b>'+esc(state.git?.commitCount??0)+'</b></span></div><div class="progress-wrap"><progress aria-label="卡片完成率 '+percent+'%" max="'+Math.max(rows.length,1)+'" value="'+done+'"></progress><span>'+percent+'%</span></div><div class="metrics">'+Object.entries(labels).filter(([s])=>s!=='done').map(([s,l])=>'<div><b>'+rows.filter(t=>t.status===s).length+'</b><span>'+l+'</span></div>').join('')+'</div></section><section><h2>处置中 <small>'+active.length+' 项</small></h2><div class="overview-task-list">'+(active.length?taskRows(active):'<p class="empty-state">当前没有处置中的任务</p>')+'</div></section></div><div class="overview-column"><section><h2>最近完成</h2><div class="overview-task-list">'+(completed.length?taskRows(completed):'<p class="empty-state">暂无已完成任务</p>')+'</div></section></div><div class="overview-column"><section><h2>最近提交</h2><div class="commit-list">'+recent.map(c=>'<article class="commit-row '+commitTone(c)+'"><span class="commit-mark">'+esc(c.subject.split(/[(:]/,1)[0]||'git')+'</span><div><strong>'+esc(c.subject)+'</strong><small>'+esc(c.hash.slice(0,8)+' · '+stamp(c.date))+'</small></div></article>').join('')+'</div>'+(!recent.length?'<p class="empty-state">没有可用的 Git 提交记录</p>':'')+'</section></div></div>';
  }
  function board(rows){
    const preferred=['in_progress','ready','pending','done'],remaining=Object.keys(labels).filter(s=>!preferred.includes(s)&&s!=='unknown');
    const order=[...preferred,...remaining,...new Set(rows.map(t=>t.status).filter(s=>!Object.hasOwn(labels,s)))];
    const available=order.filter(s=>rows.some(t=>t.status===s));
    const mobile=matchMedia('(max-width:700px)').matches;
    if(!available.includes(prefs.mobileStatus))prefs.mobileStatus=available.includes('in_progress')?'in_progress':available[0];
    $('content').innerHTML=(mobile?'<label>看板列 <select id="mobile-lane">'+available.map(s=>'<option value="'+esc(s)+'" '+(s===prefs.mobileStatus?'selected':'')+'>'+esc(labels[s]||s)+'</option>').join('')+'</select></label>':'')+'<div class="board" data-scroll="board">'+order.map(s=>{
      const items=rows.filter(t=>t.status===s);if(!items.length)return '';
      if(mobile&&s!==prefs.mobileStatus)return '';
      const collapsed=!mobile&&prefs.collapsed.includes(s);
      return '<section class="lane '+(collapsed?'collapsed':'')+'" data-status="'+esc(s)+'"><button class="lane-head" data-collapse="'+esc(s)+'" aria-expanded="'+!collapsed+'">'+esc(labels[s]||'未映射：'+s)+' <span>'+items.length+'</span> '+(collapsed?'＋':'−')+'</button><div class="cards" data-scroll="'+esc(s)+'" '+(collapsed?'hidden':'')+'>'+items.map(t=>{const detail=[t.kind&&t.kind!=='unclassified'?kinds[t.kind]||t.kind:'',blocked(t).length?'等待 '+blocked(t).length+' 项依赖':''].filter(Boolean).join(' · ');return '<button class="card" data-task="'+esc(t.id)+'"><strong>'+esc(name(t))+'</strong><p>'+esc(t.owner||'未分配')+' <span>'+esc(t.risk)+'</span></p>'+(detail?'<small>'+esc(detail)+'</small>':'')+(t.comparison?.ahead?'<small>有 '+t.comparison.ahead+' 个未合并提交</small>':'')+'</button>';}).join('')+'</div></section>';
    }).join('')+'</div>'+(rows.length?'':'<p class="empty">没有匹配任务</p>');
    document.querySelectorAll('[data-collapse]').forEach(b=>b.onclick=()=>{prefs.collapsed=prefs.collapsed.includes(b.dataset.collapse)?prefs.collapsed.filter(s=>s!==b.dataset.collapse):[...prefs.collapsed,b.dataset.collapse];save();render();});
    if($('mobile-lane'))$('mobile-lane').onchange=()=>{prefs.mobileStatus=$('mobile-lane').value;save();render();};
  }
  function graph(rows){
    const included=rows,ids=new Set(included.map(t=>t.id));
    if(!included.length){$('content').innerHTML='<p class="empty-state">没有可展示的任务</p>';return;}
    const distance=new Map();if(ids.has('TASK-001'))distance.set('TASK-001',0);
    for(let pass=0;pass<included.length;pass++){let changed=false;for(const t of included){const known=t.dependencies.filter(d=>distance.has(d));if(!known.length)continue;const next=Math.max(...known.map(d=>distance.get(d)))+1;if((distance.get(t.id)??-1)<next){distance.set(t.id,next);changed=true;}}if(!changed)break;}
    const primary=new Map(),activeDeps=new Map();
    included.forEach(t=>{const deps=t.dependencies.filter(d=>ids.has(d));activeDeps.set(t.id,deps);if(deps.length)primary.set(t.id,deps.reduce((best,d)=>(distance.get(d)??-1)>(distance.get(best)??-1)?d:best,deps[0]));});
    const buildChildren=()=>{const map=new Map(included.map(t=>[t.id,[]]));for(const [child,parent] of primary)map.get(parent)?.push(child);return map;};
    let children=buildChildren(),naturalRoots=included.filter(t=>!primary.has(t.id)).map(t=>t.id),reachable=new Set();
    const mark=id=>{if(reachable.has(id))return;reachable.add(id);for(const child of children.get(id)||[])mark(child);};naturalRoots.forEach(mark);
    for(const t of included)if(!reachable.has(t.id))primary.delete(t.id);
    children=buildChildren();naturalRoots=included.filter(t=>!primary.has(t.id)).map(t=>t.id).sort((a,b)=>a==='TASK-001'?-1:b==='TASK-001'?1:a.localeCompare(b,undefined,{numeric:true}));
    const anchor=naturalRoots.includes('TASK-001')?'TASK-001':null,roots=anchor&&!graphShowOtherRoots?[anchor]:naturalRoots;
    const pos=new Map(),edges=[];let cursor=0;
    function place(id,depth,path){
      if(path.has(id))return;
      const next=new Set(path).add(id),all=children.get(id)||[],shown=graphOpen.has(id)?all:[];
      if(!shown.length){pos.set(id,{x:260+depth*340,y:28+cursor++*124});return;}
      shown.forEach(child=>{place(child,depth+1,next);if(pos.has(child))edges.push([id,child]);});
      const ys=shown.map(child=>pos.get(child)?.y).filter(Number.isFinite);pos.set(id,{x:260+depth*340,y:ys.length?ys.reduce((a,b)=>a+b,0)/ys.length:28+cursor++*124});
    }
    roots.forEach(id=>place(id,0,new Set()));
    if(!pos.has(graphFocus))graphFocus=roots[0];
    const rootY=Math.max(28,[...pos.values()].reduce((sum,p)=>sum+p.y,0)/Math.max(pos.size,1));
    const width=Math.max(620,...[...pos.values()].map(p=>p.x+315)),height=Math.max(300,...[...pos.values()].map(p=>p.y+104));
    let svg='<svg role="img" aria-label="从左向右展开的任务依赖思维导图" width="'+width+'" height="'+height+'">';
    roots.forEach(id=>{const b=pos.get(id);if(b)svg+='<path class="mind-edge" d="M210,'+(rootY+43)+' C232,'+(rootY+43)+' 232,'+(b.y+43)+' 260,'+(b.y+43)+'"/>';});
    edges.forEach(([from,to])=>{const a=pos.get(from),b=pos.get(to);svg+='<path class="mind-edge" d="M'+(a.x+300)+','+(a.y+43)+' C'+(a.x+325)+','+(a.y+43)+' '+(b.x-24)+','+(b.y+43)+' '+b.x+','+(b.y+43)+'"/>';});
    svg+='<foreignObject x="20" y="'+(rootY+9)+'" width="190" height="70"><div xmlns="http://www.w3.org/1999/xhtml" class="mind-root">'+esc(state.project)+'</div></foreignObject>';
    const visible=included.filter(t=>pos.has(t.id)).sort((a,b)=>pos.get(a.id).y-pos.get(b.id).y||pos.get(a.id).x-pos.get(b.id).x);
    for(const t of visible){const p=pos.get(t.id),all=children.get(t.id)||[],extra=Math.max(0,(activeDeps.get(t.id)?.length||0)-1);svg+='<foreignObject x="'+p.x+'" y="'+p.y+'" width="305" height="94"><div xmlns="http://www.w3.org/1999/xhtml" class="mind-node"><button class="graph-card '+(selected===t.id?'selected':'')+'" data-task="'+esc(t.id)+'" data-status="'+esc(t.status)+'" tabindex="'+(t.id===graphFocus?'0':'-1')+'"'+(all.length?' aria-expanded="'+graphOpen.has(t.id)+'"':'')+'><span class="graph-meta"><code>'+esc(t.id)+'</code><span class="graph-status '+esc(t.status)+'">'+esc(status(t))+'</span>'+(extra?'<span>另有 '+extra+' 项前置</span>':'')+'</span><span class="graph-title">'+esc(t.title||'名称待核实')+'</span></button>'+(all.length?'<button class="mind-expand" data-expand="'+esc(t.id)+'" tabindex="-1" aria-label="'+(graphOpen.has(t.id)?'收起':'展开')+' '+esc(name(t))+'">'+(graphOpen.has(t.id)?'−':'＋')+'</button>':'')+'</div></foreignObject>';}
    svg+='</svg>';
    $('content').innerHTML='<div class="graph-controls"><button id="zoom-out">缩小</button><button id="zoom-in">放大</button><button id="fit">适应视图</button><button id="expand-roots">展开首层</button><button id="expand-all">全部展开</button><button id="collapse-all">全部收起</button>'+(anchor&&naturalRoots.length>1?'<button id="toggle-roots">'+(graphShowOtherRoots?'只看当前主干':'显示其他根任务（'+(naturalRoots.length-1)+'）')+'</button>':'')+'<small>↑↓ 选择节点 · ← 收起 · → 展开一层 · 空格展开整个右侧子树／收回当前节点。</small></div><div class="graph-port" data-scroll="graph" tabindex="0" aria-label="任务依赖图；使用方向键和空格导航"><div id="graph-plane">'+svg+'</div></div>';
    const apply=()=>{$('graph-plane').style.width=width*graphZoom+'px';$('graph-plane').style.height=height*graphZoom+'px';$('graph-plane').firstChild.style.transform='scale('+graphZoom+')';};apply();
    $('zoom-in').onclick=()=>{graphZoom=Math.min(2,graphZoom*1.2);apply();};$('zoom-out').onclick=()=>{graphZoom=Math.max(.15,graphZoom/1.2);apply();};$('fit').onclick=()=>{graphZoom=Math.min(1,Math.max(.15,($('content').clientWidth-30)/width));apply();};$('expand-roots').onclick=()=>{roots.forEach(id=>graphOpen.add(id));render();};$('expand-all').onclick=()=>{graphShowOtherRoots=true;included.forEach(t=>{if((children.get(t.id)||[]).length)graphOpen.add(t.id);});render();};$('collapse-all').onclick=()=>{graphOpen.clear();render();};
    if($('toggle-roots'))$('toggle-roots').onclick=()=>{graphShowOtherRoots=!graphShowOtherRoots;graphOpen.clear();render();};
    const descendants=id=>{const found=[];const visit=x=>{for(const child of children.get(x)||[]){if(found.includes(child))continue;found.push(child);visit(child);}};visit(id);return found;};
    const collapse=id=>{graphOpen.delete(id);descendants(id).forEach(x=>graphOpen.delete(x));};
    const redraw=id=>{graphFocus=id;render();requestAnimationFrame(()=>[...document.querySelectorAll('.graph-card')].find(b=>b.dataset.task===id)?.focus());};
    document.querySelectorAll('[data-expand]').forEach(b=>b.onclick=e=>{e.stopPropagation();graphFocus=b.dataset.expand;if(graphOpen.has(b.dataset.expand))collapse(b.dataset.expand);else graphOpen.add(b.dataset.expand);redraw(b.dataset.expand);});
    const navigate=e=>{if(!['ArrowDown','ArrowUp','ArrowRight','ArrowLeft',' ','Spacebar'].includes(e.key))return;const id=graphFocus&&pos.has(graphFocus)?graphFocus:roots[0],all=children.get(id)||[],cards=[...document.querySelectorAll('.graph-card')],current=cards.find(b=>b.dataset.task===id),index=Math.max(0,cards.indexOf(current));e.preventDefault();e.stopPropagation();if(e.key==='ArrowDown'||e.key==='ArrowUp'){const next=cards[index+(e.key==='ArrowDown'?1:-1)];if(next){graphFocus=next.dataset.task;next.focus();}}else if(e.key==='ArrowRight'){if(all.length&&!graphOpen.has(id)){graphOpen.add(id);redraw(id);}else if(all.length){redraw(all[0]);}}else if(e.key==='ArrowLeft'){if(graphOpen.has(id)){collapse(id);redraw(id);}else if(primary.has(id)){redraw(primary.get(id));}}else{const branch=descendants(id),expanded=graphOpen.has(id)||branch.some(x=>graphOpen.has(x));if(expanded)collapse(id);else{if(all.length)graphOpen.add(id);branch.forEach(x=>{if((children.get(x)||[]).length)graphOpen.add(x);});}redraw(id);}};
    document.querySelectorAll('.graph-card').forEach(b=>{b.onfocus=()=>graphFocus=b.dataset.task;b.onkeydown=navigate;});
    const port=$('graph-plane').parentElement;port.onkeydown=navigate;let drag;
    port.onpointerdown=e=>{if(e.target.closest('button'))return;port.focus({preventScroll:true});drag={x:e.clientX,y:e.clientY,left:port.scrollLeft,top:port.scrollTop};port.setPointerCapture(e.pointerId);};port.onpointermove=e=>{if(drag){port.scrollLeft=drag.left+drag.x-e.clientX;port.scrollTop=drag.top+drag.y-e.clientY;}};port.onpointerup=()=>drag=null;port.onpointercancel=()=>drag=null;
  }
  function architecture(){
    if(!state.architecture){$('content').innerHTML='<section class="architecture empty"><h2>Architecture</h2><p>未找到架构文档。默认读取 <code>.tasks/architecture.md</code>，也可通过 <code>--architecture FILE.md</code> 指定。</p></section>';return;}
    $('content').innerHTML='<article class="architecture"><div class="architecture-meta">Markdown 渲染 · '+esc(state.architecture.path)+'</div>'+markdown(state.architecture.markdown)+'</article>';
  }
  async function api(path,options){const r=await fetch(path,options);const data=await r.json();if(!r.ok)throw new Error(data.error||'请求失败');return data;}
  function open(id){if(!$('detail').open){returnTask=id;lastFocus=document.activeElement;$('detail').showModal();}selected=id;selectedWt='';tab='requirements';detail();if(prefs.view==='graph')render();}
  function detail(){
    const t=task(selected);if(!t){$('detail-body').textContent='任务已从输入移除';return;}
    const taskIndex=state.tasks.findIndex(x=>x.id===t.id),previous=taskIndex>0?state.tasks[taskIndex-1]:null,next=taskIndex>=0&&taskIndex<state.tasks.length-1?state.tasks[taskIndex+1]:null,origin=task(returnTask);
    $('previous-task').disabled=!previous;$('previous-task').title=previous?'切换到 '+name(previous):'已经是第一个任务';
    $('next-task').disabled=!next;$('next-task').title=next?'切换到 '+name(next):'已经是最后一个任务';
    $('return-task').disabled=!origin||origin.id===t.id;$('return-task').title=origin&&origin.id!==t.id?'返回 '+name(origin):'当前就是最初打开的任务';
    generation++;$('detail-title').textContent=name(t);$('detail-tabs').innerHTML=[['requirements','业务要求'],['evidence','依赖与验收'],['worktree','工作区'],['git','Git 历史']].map(([id,label])=>'<button data-tab="'+id+'" aria-pressed="'+(tab===id)+'">'+label+'</button>').join('');
    document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;detail();});
    const body=$('detail-body');
    if(tab==='requirements'){const optionalMeta=(t.group?'<div><span>任务分组</span><strong>'+esc(t.group)+'</strong></div>':'')+(t.kind&&t.kind!=='unclassified'?'<div><span>工作类型</span><strong>'+esc(kinds[t.kind]||t.kind)+'</strong></div>':'');body.innerHTML='<section class="detail-hero"><div>'+badge(t)+'<span class="risk-chip">'+esc(t.risk||'风险未标注')+'</span></div><p>'+esc(t.goal||'未记录目标')+'</p></section><div class="detail-meta"><div><span>负责人</span><strong>'+esc(t.owner||'未分配')+'</strong></div><div><span>领取时间</span><strong>'+esc(stamp(t.claimedAt))+'</strong></div>'+optionalMeta+'</div><h3 class="section-title">工作范围</h3><div class="scope-grid">'+scopeView(t.scope)+'</div>';}
    if(tab==='evidence'){
      const downstream=state.tasks.filter(x=>x.dependencies.includes(t.id));
      body.innerHTML='<section class="detail-section"><h3>任务关系</h3><div class="relation-grid"><div><span class="section-label">前置任务</span>'+(t.dependencies.length?t.dependencies.map(id=>task(id)?'<div class="relation-item">'+button(task(id))+' '+badge(task(id))+'</div>':'<div class="relation-item warning">未知任务：'+esc(id)+'</div>').join(''):'<p class="empty-state">没有前置任务</p>')+'</div><div><span class="section-label">后续任务</span>'+(downstream.length?downstream.map(x=>'<div class="relation-item">'+button(x)+' '+badge(x)+'</div>').join(''):'<p class="empty-state">没有后续任务</p>')+'</div></div></section><section class="detail-section"><h3>验收要求 <small>'+t.acceptance.length+' 项</small></h3><div class="acceptance-list">'+(t.acceptance.length?t.acceptance.map((a,i)=>'<article class="acceptance-item"><span>'+(i+1)+'</span><div><small>'+esc(typeof a==='object'&&a?.type?a.type:'验收条件')+'</small><p>'+esc(acceptanceText(a))+'</p></div></article>').join(''):'<p class="empty-state">未记录验收要求</p>')+'</div></section><section class="detail-section"><h3>验收证据 <small>'+t.evidence.length+' 条</small></h3><div class="evidence-list">'+(t.evidence.length?t.evidence.map(e=>typeof e==='string'?'<article class="evidence-card"><p>'+esc(e)+'</p></article>':'<article class="evidence-card '+(e.status==='passed'?'evidence-passed':e.status==='failed'?'evidence-failed':'')+'"><div class="evidence-head"><span class="evidence-status">'+esc(e.status||'状态未知')+'</span><small>'+esc(e.type||'evidence')+'</small></div><strong>'+esc(e.check||'未命名检查')+'</strong><p>'+esc(e.summary||'未记录说明')+'</p></article>').join(''):'<p class="empty-state">尚无证据，不能推断验收通过</p>')+'</div></section>';
    }
    if(tab==='worktree') {
      const ws=state.git.worktrees.filter(w=>t.candidates.includes(w.id));
      body.innerHTML='<div class="detail-meta"><div><span>关联方式</span><strong>'+esc({explicit:'显式关联',inferred:'按任务 ID 推断',unknown:'未知'}[t.association])+'</strong></div><div><span>分支</span><strong>'+esc(t.resolvedBranch||t.branch||'未知')+'</strong></div><div><span>领先 / 落后</span><strong>'+(t.comparison?esc(t.comparison.ahead+' / '+t.comparison.behind):'未知')+'</strong></div><div><span>集成状态</span><strong>'+(t.comparison?(t.comparison.merged?'已包含于基准':'存在未合并提交'):'基准对比未知')+'</strong></div></div>'+(ws.length>1?'<p class="notice">存在多个候选，请选择需要查看的工作区。</p>':'')+'<div class="worktree-list">'+ws.map(w=>'<article class="worktree-card"><div class="worktree-head"><h3>'+esc(w.branch||'Detached HEAD')+'</h3><span class="dirty-count">'+(!w.exists?'目录不存在':w.dirty.length+' 个未提交文件')+'</span></div><code class="path-line">'+esc(w.path)+'</code><div class="action-row"><button data-copy="'+esc(w.path)+'">复制路径</button>'+(live&&w.exists?'<button data-open="'+w.id+'">在文件管理器打开</button>':'')+'</div>'+(w.dirty.length?'<details><summary>查看未提交文件</summary><ul class="file-list">'+w.dirty.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></details>':'')+'</article>').join('')+'</div>'+(!ws.length?'<div class="empty-state">没有登记的工作区'+(t.worktree?'<code class="path-line">'+esc(t.worktree)+'</code><button data-copy="'+esc(t.worktree)+'">复制记录路径</button>':'')+'</div>':'');
      body.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.copy);b.textContent='已复制';}catch{b.textContent='请从上方路径手动复制';}});
      body.querySelectorAll('[data-open]').forEach(b=>b.onclick=async()=>{try{await api('/api/open',{method:'POST',headers:{'Content-Type':'application/json','X-Preview-Token':token},body:JSON.stringify({id:b.dataset.open})});b.textContent='已打开';}catch(e){b.textContent=e.message;}});
    }
    if(tab==='git') {
      body.innerHTML='<p>读取 Git 历史…</p>';
      const ws=state.git.worktrees.filter(w=>t.candidates.includes(w.id));
      if(ws.length>1&&!selectedWt){body.innerHTML='<p>选择工作区历史</p>'+ws.map(w=>'<button data-wt="'+w.id+'">'+esc(w.branch||w.path)+'</button>').join('');body.querySelectorAll('[data-wt]').forEach(b=>b.onclick=()=>{selectedWt=b.dataset.wt;detail();});return;}
      showHistory(t,0,false,generation);
    }
    bindTasks(body);
  }
  async function showHistory(t,offset,append,version){
    try {
      const data=live?await api('/api/history?task='+encodeURIComponent(t.id)+'&offset='+offset+(selectedWt?'&worktree='+selectedWt:'')):state.histories?.[t.id];
      if(version!==generation||tab!=='git')return;
      if(!data)throw new Error('快照未包含该分支历史；请使用实时模式');
      if(!append)$('detail-body').innerHTML='<div id="commits"></div><div id="more"></div>';
      $('commits').insertAdjacentHTML('beforeend',data.commits.map(c=>'<article class="history-card '+commitTone(c)+'"><button class="commit" data-hash="'+c.hash+'"><span class="commit-mark">'+esc(c.subject.split(/[(:]/,1)[0]||'git')+'</span><span>'+esc(c.subject)+'</span></button><div class="history-meta"><code>'+esc(c.hash.slice(0,10))+'</code><span>'+esc(stamp(c.date))+'</span><span>'+(c.inBase===null?'基准未知':c.inBase?'已包含于基准':'未包含于基准')+'</span></div><pre hidden></pre></article>').join(''));
      $('more').innerHTML=data.hasMore&&live?'<button id="load-more">加载更多</button>':!live?'<p>静态快照：仅保存有限历史，完整记录请使用实时模式。</p>':'';
      if($('load-more'))$('load-more').onclick=()=>showHistory(t,offset+30,true,version);
      $('commits').querySelectorAll('[data-hash]').forEach(b=>b.onclick=async()=>{const pre=b.parentElement.querySelector('pre');pre.hidden=false;try{const files=live?await api('/api/commit?task='+encodeURIComponent(t.id)+'&hash='+b.dataset.hash+(selectedWt?'&worktree='+selectedWt:'')):state.commitFiles?.[b.dataset.hash];if(!files)throw new Error('文件统计请在实时模式查看');pre.textContent=files.map(f=>'+'+f.added+' −'+f.deleted+' '+f.path).join('\n')||'无文件变更';}catch(e){pre.textContent=e.message;}});
    }catch(e){if(version===generation)$('detail-body').textContent=e.message;}
  }
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{prefs.view=b.dataset.view;save();render();if(prefs.view==='graph')requestAnimationFrame(()=>$('content').querySelector('.graph-port')?.focus());});
  $('query').addEventListener('input',()=>{prefs.query=$('query').value;save();render();});
  $('theme-toggle').onclick=()=>{prefs.theme=prefs.theme==='dark'?'light':'dark';save();render();};
  const navigateTask=offset=>{const i=state.tasks.findIndex(t=>t.id===selected),target=state.tasks[i+offset];if(target){selected=target.id;selectedWt='';detail();}};
  $('previous-task').onclick=()=>navigateTask(-1);$('next-task').onclick=()=>navigateTask(1);$('return-task').onclick=()=>{if(task(returnTask)){selected=returnTask;selectedWt='';detail();}};
  $('close').onclick=()=>$('detail').close();$('detail').addEventListener('close',()=>{generation++;returnTask=null;lastFocus?.focus();});
  render();
  matchMedia('(max-width:700px)').addEventListener('change',render);
  if(live){let fingerprint=JSON.stringify([state.project,state.projectStatus,state.tasks,state.git,state.milestones,state.architecture]);async function tick(){try{const next=await api('/api/state');$('error').textContent='';const nextKey=JSON.stringify([next.project,next.projectStatus,next.tasks,next.git,next.milestones,next.architecture]);state=next;if(nextKey!==fingerprint){fingerprint=nextKey;render();if($('detail').open)detail();}}catch(e){$('error').textContent='刷新失败，保留 '+stamp(state.generatedAt)+' 的数据：'+e.message;}finally{setTimeout(tick,3000);}}setTimeout(tick,3000);}
}

